import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private static final String PATH = "/v1/authorizations";

    private WireMockServer provider;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() {
        provider = new WireMockServer(WireMockConfiguration.options().dynamicPort());
        provider.start();
        gateway = new HttpPaymentGateway(RestClient.builder().baseUrl(provider.baseUrl()).build());
    }

    @AfterEach
    void stopProvider() {
        provider.stop();
    }

    @Test
    void the_authorization_request_is_sent_as_json_with_reference_amount_and_currency() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(200, "{\"status\":\"approved\"}")));

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        provider.verify(1, postRequestedFor(urlEqualTo(PATH))
                .withHeader("Content-Type", com.github.tomakehurst.wiremock.client.WireMock.containing("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}", false, false)));
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(200, "{\"status\":\"approved\"}")));

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(200, "{\"status\":\"declined\"}")));

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        provider.stubFor(post(urlEqualTo(PATH))
                .willReturn(json(200, "{\"status\":\"approved\",\"id\":\"a1\",\"risk\":{\"score\":3}}")));

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_refusal_with_402_is_read_as_declined() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(402, "{\"error\":\"card_refused\"}")));

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_provider_failure_is_reported_instead_of_being_taken_for_a_decision() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(aResponse().withStatus(500)));

        assertThatThrownBy(this::authorize).isInstanceOf(IllegalStateException.class).hasMessageContaining("500");
    }

    @Test
    void a_request_the_provider_rejects_is_reported_instead_of_being_taken_for_a_decision() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(400, "{\"error\":\"invalid_request\"}")));

        assertThatThrownBy(this::authorize).isInstanceOf(IllegalStateException.class).hasMessageContaining("400");
    }

    @Test
    void an_unknown_status_is_never_read_as_approved() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(200, "{\"status\":\"pending\"}")));

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_read_as_approved() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(json(200, "{\"decision\":\"approved\"}")));

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    private AuthorizationOutcome authorize() {
        return gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));
    }

    private static com.github.tomakehurst.wiremock.client.ResponseDefinitionBuilder json(int status, String body) {
        return aResponse().withStatus(status).withHeader("Content-Type", "application/json").withBody(body);
    }
}
